CREATE TABLE `card_decks` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL);
CREATE TABLE `mistakes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `subjectId` INTEGER NOT NULL, `topic` TEXT NOT NULL, `question` TEXT NOT NULL, `reason` TEXT NOT NULL, `solution` TEXT NOT NULL, FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `activity_timers` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `mode` TEXT NOT NULL, `title` TEXT NOT NULL, `bookId` INTEGER, `startedAt` INTEGER NOT NULL, `runningSince` INTEGER, `elapsedMs` INTEGER NOT NULL, `endedAt` INTEGER, `series` TEXT NOT NULL, `restUntil` INTEGER NOT NULL);
CREATE TABLE `reading_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `pages` INTEGER NOT NULL, `loggedAt` INTEGER NOT NULL);
CREATE TABLE `subjects` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `color` INTEGER NOT NULL, `nextStep` TEXT);
CREATE TABLE `study_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `subjectId` INTEGER, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER NOT NULL, `durationSeconds` INTEGER NOT NULL, `isActive` INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `subject_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `subjectId` INTEGER NOT NULL, `type` TEXT NOT NULL, `title` TEXT NOT NULL, `details` TEXT NOT NULL, `targetAt` INTEGER, `currentValue` REAL NOT NULL, `targetValue` REAL, `unit` TEXT NOT NULL, `completed` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `question_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `subjectId` INTEGER, `topic` TEXT NOT NULL, `questionCount` INTEGER NOT NULL, `correctCount` INTEGER NOT NULL, `loggedAt` INTEGER NOT NULL, FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `workout_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `exercises` TEXT NOT NULL, `durationMinutes` INTEGER NOT NULL, `notes` TEXT NOT NULL, `startedAt` INTEGER NOT NULL);
CREATE TABLE `meal_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `mealType` TEXT NOT NULL, `foods` TEXT NOT NULL, `calories` INTEGER NOT NULL, `proteinGrams` REAL NOT NULL, `carbsGrams` REAL NOT NULL, `fatGrams` REAL NOT NULL, `loggedAt` INTEGER NOT NULL);
CREATE TABLE `journal_entries` (`dayKey` INTEGER NOT NULL, `title` TEXT NOT NULL, `body` TEXT NOT NULL, `mood` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`dayKey`));
CREATE TABLE `calendar_events` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `at` INTEGER NOT NULL);
CREATE TABLE `study_tasks` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `subjectId` INTEGER, `title` TEXT NOT NULL, `dueAt` INTEGER NOT NULL, `completed` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `completedAt` INTEGER, `previousTaskId` INTEGER, `priority` INTEGER NOT NULL DEFAULT 4, `recurrence` TEXT NOT NULL DEFAULT 'NONE', `noteId` INTEGER, `details` TEXT NOT NULL DEFAULT '', FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `habit_areas` (`name` TEXT NOT NULL, `sortOrder` INTEGER NOT NULL, PRIMARY KEY(`name`));
CREATE TABLE `habits` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `emoji` TEXT NOT NULL DEFAULT '✨', `createdAt` INTEGER NOT NULL, `area` TEXT NOT NULL DEFAULT 'Dia', `kind` TEXT NOT NULL DEFAULT 'GOOD', `repeatDaysMask` INTEGER NOT NULL DEFAULT 127, `targetValue` REAL NOT NULL DEFAULT 1.0, `targetUnit` TEXT NOT NULL DEFAULT 'vezes', `targetPeriod` TEXT NOT NULL DEFAULT 'dia', `reminderMinutes` INTEGER);
CREATE TABLE `habit_completions` (`habitId` INTEGER NOT NULL, `dayKey` INTEGER NOT NULL, `status` TEXT NOT NULL DEFAULT 'DONE', `value` REAL NOT NULL DEFAULT 1.0, `note` TEXT, `loggedAt` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`habitId`, `dayKey`), FOREIGN KEY(`habitId`) REFERENCES `habits`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `goals` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `targetAt` INTEGER NOT NULL, `completed` INTEGER NOT NULL, `direction` TEXT NOT NULL DEFAULT 'COUNTDOWN', `unit` TEXT NOT NULL DEFAULT 'DAYS', `roundUp` INTEGER NOT NULL DEFAULT 1, `color` INTEGER NOT NULL DEFAULT 4284569305, `style` TEXT NOT NULL DEFAULT 'RING', `createdAt` INTEGER NOT NULL DEFAULT 0);
CREATE TABLE `notes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `markdown` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, `pinned` INTEGER NOT NULL DEFAULT 0);
CREATE TABLE `books` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `author` TEXT NOT NULL, `coverUri` TEXT, `summary` TEXT NOT NULL, `currentPage` INTEGER NOT NULL, `totalPages` INTEGER, `quotes` TEXT NOT NULL, `status` TEXT NOT NULL, `subjectId` INTEGER, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `book_note_links` (`bookId` INTEGER NOT NULL, `noteId` INTEGER NOT NULL, PRIMARY KEY(`bookId`, `noteId`), FOREIGN KEY(`bookId`) REFERENCES `books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`noteId`) REFERENCES `notes`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `flashcards` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `subjectId` INTEGER, `front` TEXT NOT NULL, `back` TEXT NOT NULL, `dueAt` INTEGER NOT NULL, `intervalDays` INTEGER NOT NULL, `easeFactor` REAL NOT NULL, `repetitions` INTEGER NOT NULL, `sourceNoteId` INTEGER, `sourceExcerpt` TEXT, `deckId` INTEGER, `lapses` INTEGER NOT NULL, FOREIGN KEY(`deckId`) REFERENCES `card_decks`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL , FOREIGN KEY(`subjectId`) REFERENCES `subjects`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `card_reviews` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `cardId` INTEGER NOT NULL, `reviewedAt` INTEGER NOT NULL, `grade` INTEGER NOT NULL, `intervalDays` INTEGER NOT NULL, FOREIGN KEY(`cardId`) REFERENCES `flashcards`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX `index_card_decks_name` ON `card_decks` (`name`);
CREATE INDEX `index_mistakes_subjectId` ON `mistakes` (`subjectId`);
CREATE INDEX `index_study_sessions_subjectId` ON `study_sessions` (`subjectId`);
CREATE INDEX `index_subject_items_subjectId` ON `subject_items` (`subjectId`);
CREATE INDEX `index_subject_items_type` ON `subject_items` (`type`);
CREATE INDEX `index_subject_items_targetAt` ON `subject_items` (`targetAt`);
CREATE INDEX `index_question_logs_subjectId` ON `question_logs` (`subjectId`);
CREATE INDEX `index_question_logs_loggedAt` ON `question_logs` (`loggedAt`);
CREATE INDEX `index_workout_logs_startedAt` ON `workout_logs` (`startedAt`);
CREATE INDEX `index_meal_logs_loggedAt` ON `meal_logs` (`loggedAt`);
CREATE INDEX `index_study_tasks_subjectId` ON `study_tasks` (`subjectId`);
CREATE INDEX `index_habits_area` ON `habits` (`area`);
CREATE INDEX `index_habits_createdAt` ON `habits` (`createdAt`);
CREATE INDEX `index_habit_completions_dayKey` ON `habit_completions` (`dayKey`);
CREATE INDEX `index_books_subjectId` ON `books` (`subjectId`);
CREATE INDEX `index_book_note_links_noteId` ON `book_note_links` (`noteId`);
CREATE INDEX `index_flashcards_subjectId` ON `flashcards` (`subjectId`);
CREATE INDEX `index_flashcards_dueAt` ON `flashcards` (`dueAt`);
CREATE INDEX `index_flashcards_deckId` ON `flashcards` (`deckId`);
CREATE INDEX `index_card_reviews_cardId` ON `card_reviews` (`cardId`);
CREATE INDEX `index_card_reviews_reviewedAt` ON `card_reviews` (`reviewedAt`);
